mapper.select:
    SELECT tenant_id, outbox_id, status, attempt_count, locked_by,
       correlation_id, lock_version
FROM outbox_event
WHERE contract_ref = #{contractRef}
  AND contract_version = #{contractVersion}
  AND aggregate_type = #{aggregateType}
  AND attempt_count <= #{maxAutomaticSends}
  AND (
       (status = 'PENDING' AND next_attempt_at <= #{now})
       OR
       (status = 'PUBLISHING' AND locked_at <= #{leaseCutoff})
  )
ORDER BY CASE WHEN status = 'PENDING' THEN next_attempt_at ELSE locked_at END,
         tenant_id, outbox_id
LIMIT #{limit}

mapper.update:
    UPDATE outbox_event
SET attempt_count = attempt_count + 1,
    locked_by = #{claimToken},
    locked_at = #{claimedAt},
    lock_version = lock_version + 1,
    updated_at = #{claimedAt2},
    updated_by_type = 'SERVICE',
    updated_by_id = NULL
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId}
  AND status = 'PUBLISHING'
  AND attempt_count = #{attemptCount} AND attempt_count < #{maxAutomaticSends}
  AND locked_by = #{lockedBy}
  AND lock_version = #{lockVersion}
  AND locked_at <= #{leaseCutoff}

    UPDATE outbox_event
SET status = 'PUBLISHING',
    locked_by = #{claimToken},
    locked_at = #{claimedAt},
    lock_version = lock_version + 1,
    updated_at = #{claimedAt2},
    updated_by_type = 'SERVICE',
    updated_by_id = NULL
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId}
  AND status = 'PENDING'
  AND attempt_count = #{maxAutomaticSends}
  AND lock_version = #{lockVersion}
  AND next_attempt_at <= #{claimedAt3}

    UPDATE outbox_event
SET locked_by = #{claimToken},
    locked_at = #{claimedAt},
    lock_version = lock_version + 1,
    updated_at = #{claimedAt2},
    updated_by_type = 'SERVICE',
    updated_by_id = NULL
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId}
  AND status = 'PUBLISHING'
  AND attempt_count = #{maxAutomaticSends}
  AND locked_by = #{lockedBy}
  AND lock_version = #{lockVersion}
  AND locked_at <= #{leaseCutoff}

    UPDATE outbox_event
SET status = 'PUBLISHED',
    locked_by = NULL,
    locked_at = NULL,
    last_error_code = NULL,
    broker_confirmed_at = #{confirmedAt},
    lock_version = lock_version + 1,
    updated_at = #{confirmedAt2},
    updated_by_type = 'SERVICE',
    updated_by_id = NULL
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId}
  AND status = 'PUBLISHING'
  AND attempt_count = #{attemptCount}
  AND locked_by = #{claimToken}
  AND lock_version = #{lockVersion}
  AND locked_at > #{leaseCutoff}

mapper.select:
    SELECT status, lock_version
FROM workflow_start_link
WHERE tenant_id = #{tenantId} AND ticket_id = #{aggregateId}

    SELECT tenant_id, outbox_id, message_id, publication_key, business_intent_key,
       aggregate_type, aggregate_id, contract_ref, contract_version, body_bytes,
       body_sha256, correlation_id, causation_id, attempt_count, locked_by,
       locked_at, lock_version, created_at
FROM outbox_event
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId}
  AND status = 'PUBLISHING'
  AND attempt_count = #{attemptCount}
  AND locked_by = #{claimToken}
  AND lock_version = #{lockVersion}

    SELECT business_intent_key, state, attempt_count, dead_lettered_at
FROM message_recovery
WHERE tenant_id = #{tenantId} AND direction = 'OUTBOX' AND source_record_id = #{outboxId}
